-------------------------------------------------------------------------------------------------------------------------------------------------------------
-- configuration file for the front line director plugin
--
-- This configuration is tailored for a mission generated by DCS Retribution
-- see https://github.com/dcs-retribution/dcs-retribution
-------------------------------------------------------------------------------------------------------------------------------------------------------------

if dcsRetribution and FLD then
    if dcsRetribution.plugins and dcsRetribution.plugins.frontlinedirector then
        local options = dcsRetribution.plugins.frontlinedirector
        FLD.config.showMarks = options.showMarks ~= false
        FLD.config.messages = options.messages ~= false
        FLD.config.statusMenu = options.statusMenu ~= false
        FLD.config.popupEvents = options.popupEvents ~= false
        FLD.config.battleSmoke = options.battleSmoke ~= false
        FLD.config.debug = options.debug == true
    end
    FLD.init(dcsRetribution.FrontLineDirector)
end
